def build():
    cats = json.loads((BASE / 'data/participant3/categories.json').read_text())
    audit = json.loads((BASE / 'reports/participant3/section_parameter_audit.json').read_text())
    roots = {cid for cid, c in cats.items() if not c.get('@parentId')}
    missing, extra = roots - PROFILES.keys(), PROFILES.keys() - roots
    if missing or extra:
        raise ValueError(f'Root coverage mismatch: missing={missing}, extra={extra}')
    sections = []
    for cid in sorted(roots, key=lambda r: (cats[r]['#text'].casefold(), r)):
        fields, notes = PROFILES[cid]
        attributes = [x.strip() for x in fields.split(';')]
        if not attributes or len(set(attributes)) != len(attributes):
            raise ValueError(f'Empty or duplicate attribute names for {cid}')
        evidence = audit['sections'][cid]
        sections.append({
            'category_id': cid,
            'category_name': cats[cid]['#text'],
            'primary_attribute_labels': attributes,
            'applicability': 'Select by actual product subtype; not every field applies to every descendant.',
            'specialization_notes': notes,
            'child_categories': evidence['child_categories'],
            'catalog_prefix_offer_count': evidence['pilot_offers'],
            'observed_parameter_names_in_prefix': evidence['parameter_names_in_pilot'],
            'required_leaf_attributes': None,
        })
    proposal = {
        'version': '0.1',
        'status': 'working_team_proposal',
        'scope': 'all_96_catalog_root_sections',
        'runtime_ready': False,
        'official_organizer_attribute_schema': False,
        'source': 'Organizer catalog category tree; section metadata and parameter audit of first 5000 offers.',
        'common_physical_product_attribute_labels': ['Бренд самого товара', 'Модель самого товара', 'Тип товара',
            'Цвет товара', 'Материал конкретной части', 'Габариты товара', 'Масса товара', 'Количество в упаковке'],
        'common_fields_policy': 'When applicable and supported by input evidence; no unconditional requirements for digital goods or services.',
        'rules': [
            'Brand/model of a compatible host device are not brand/model of the sold accessory.',
            'Keep original field, exact evidence and units; no reconstruction from world knowledge.',
            'Separate product/packaging dimensions, net/gross weights, installed/supported capacities, input/output power.',
            'Select a smaller target set per leaf subtype; do not train all root attributes on every descendant.',
            'Unknown is distinct from verified absent; annotation coverage must be explicit.',
            'Use missing/null for unsupported values, review for ambiguous/conflicting values, explicit error for backend failures.',
            'Raw model scores are not automatically calibrated probabilities; current auto-accept remains disabled.',
            'Nested values, multi-part kits and conditional metrics require scoped/multiple values, not silent scalar flattening.',
            'Observed parameter counts concern the first 5000 offers only; zero does not prove full-catalog absence.',
            'Commercial/service fields do not expose secret activation codes, card numbers or PINs.',
        ],
        'sections': sections,
    }
    output = BASE / 'output/team'
    output.mkdir(parents=True, exist_ok=True)
    json_path = output / 'Основные_характеристики_96_разделов.json'
    md_path = output / 'Основные_характеристики_96_разделов.md'
    json_path.write_text(json.dumps(proposal, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    lines = [
        '# Основные характеристики всех 96 разделов каталога', '',
        'Рабочая схема команды по предоставленному каталогу. Это полный охват разделов верхнего уровня, но не официальный список организатора и не окончательная таксономия всех 5788 конечных категорий.', '',
        'Названия и ID разделов взяты из данных. Предложения учитывают фактические дочерние категории и аудит параметров первых 5000 товаров. Для разделов без карточек в пилоте набор составлен по дереву и назначению категории; наличие параметров в полном датасете ещё нужно проверить. Наличие поля в этом документе не означает, что текущая модель уже умеет его извлекать.', '',
        '## Общие поля и применение', '',
        'У физических товаров проверяем бренд, модель, тип, цвет, материал конкретной части, габариты, массу и количество в упаковке, где они применимы. Не каждый товар имеет модель или материал, указанные в тексте. У услуг и цифровых предложений вместо физических параметров используются поставщик, вид предложения и условия доступа или работ.', '',
        'Перечень раздела — набор основных кандидатов. Для конкретной подкатегории выбирается подходящий поднабор: пылесосу — пылесборник, аксессуару — совместимость; чайнику — объём, ножу — длина лезвия. Общие поля здесь не повторяются в каждой строке, если не требуют отдельного пояснения.', '',
        '## Перечень по всем разделам', '',
        '| № | Раздел — ID | Основные характеристики помимо применимых общих полей |',
        '|---|---|---|',
    ]
    for i, section in enumerate(sections, 1):
        name = section['category_name'].replace('|', '\\|')
        attributes = '; '.join(section['primary_attribute_labels']).replace('|', '\\|')
        lines.append(f'| {i} | {name} — `{section["category_id"]}` | {attributes} |')
    lines += ['', '## Уточнения по подкатегориям', '']
    for i, section in enumerate(sections, 1):
        lines += [f'### {i}. {section["category_name"]} — ID {section["category_id"]}', '',
                  section['specialization_notes'], '',
                  f'Карточек в пилоте, включая потомков: **{section["catalog_prefix_offer_count"]}**. ' +
                  ('Свойства пока предложены по дереву; карточки этого раздела не попали в первые 5000.'
                   if not section['catalog_prefix_offer_count'] else
                   'Это объём префикса, а не всего раздела; даже наблюдаемые параметры требуют проверки разметки.'), '']
    lines += [
        '## Единые правила извлечения', '',
        '- Извлекаем только значения, подтверждённые входным текстом; сохраняем поле, фрагмент и позиции. Знание названия модели не доказывает остальные характеристики.',
        '- Различаем бренд/модель товара и совместимого устройства. Не превращаем совместимость чехла с iPhone в бренд чехла Apple.',
        '- Не смешиваем RAM, VRAM и накопитель, установленную и поддерживаемую ёмкость, входную и выходную мощность, габариты товара и упаковки, массу нетто и брутто.',
        '- Число всегда сохраняет смысл, единицу и условия: мощность на канал, шум конкретного режима, кадры в секунду при конкретном разрешении. Не усредняем и не выбираем одно значение молча.',
        '- Наборы, составы и совместимость могут иметь несколько значений. Материалы разных частей и компоненты комплекта хранятся раздельно; текущий скалярный resolver требует согласованного расширения для таких случаев.',
        '- GB/TB и GiB/TiB, W и VA, W и Pa, Wh и mAh, мм и мм² не объявляются синонимами. Нормализация общая для четырёх подходов, исходное значение сохраняется.',
        '- У одежды и обуви размер хранится с системой размеров. У продуктов пищевая ценность сохраняет основу: на порцию, на 100 г или на 100 мл.',
        '- Нет подтверждённого значения — missing/null; неоднозначность или конфликт — review; сбой извлекателя — error. Не назначаем искусственную уверенность и не называем raw score вероятностью.',
        '- Секретные коды, PIN и номера подарочных карт не являются целевыми публичными характеристиками.',
        '', '## Как превратить список в обучающую таксономию', '',
        '1. По всему каталогу подсчитать уникальные товары, названия/единицы параметров и их поддержку по ID конечных категорий. Префикс из 5000 товаров не заменяет этот аудит.',
        '2. Для каждой подкатегории выбрать основные поля и явно описать применимость. Значения, не размеченные в эталоне, не объявлять отрицательными.',
        '3. Объединить смысловые синонимы, назначить стабильные attribute_id, типы, единицы, нормализацию и допустимую множественность. При различии смысла оставить отдельные ID.',
        '4. Перенести результат в общую taxonomy.yaml участника № 1 и нормализатор участника № 2. Этот документ не подключён как готовая runtime-конфигурация.',
        '5. Подготовить и проверить примеры для новых полей, затем обучать и сравнивать все четыре подхода на одном split и эталоне. Существующие checkpoint пока обучались лишь на прежних восьми ID.', '',
        f'Машиночитаемое предложение с дочерними категориями и наблюдаемыми параметрами: [{json_path.name}]({json_path}).', '',
        f'Аудит параметров пилота: [section_parameter_audit.json]({BASE / "reports/participant3/section_parameter_audit.json"}).',
    ]
    md_path.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    verified = json.loads(json_path.read_text())
    ids = [s['category_id'] for s in verified['sections']]
    assert len(ids) == len(set(ids)) == len(roots) == 96
    assert set(ids) == roots
    assert sum(s['catalog_prefix_offer_count'] for s in sections) == 5000
    assert all(s['primary_attribute_labels'] and s['specialization_notes'] for s in sections)
    print(json.dumps({'sections': len(ids), 'exact_catalog_root_coverage': True,
                      'pilot_offers': 5000, 'files': [str(md_path), str(json_path)]}, ensure_ascii=False))


if __name__ == '__main__':
    build()
